/**
 * Translate child Engine StreamEvents into ChatEntry-shaped objects so the
 * AgentDock detail view (which reuses App.renderEntry) can show a sub-agent's
 * conversation in the same visual language as the main feed.
 *
 * The transcript is the canonical record for one background sub-agent. State
 * (current thinking entry, currently-streaming assistant_text, in-flight
 * tool_start map) lives in a per-agent translator. Each translator instance
 * appends ChatEntry-shaped objects via `append` and mutates them via `update`,
 * mirroring how App.tsx's handleStreamEvent talks to chatStore but isolated to
 * a single agent's transcript.
 *
 * The output shapes intentionally match `src/ui/store.ts#ChatEntryData` so the
 * existing renderEntry switch picks them up without code changes.
 */
import type { StreamEvent } from "../../types.js";
import { asyncAgentRegistry, type AgentTranscriptEntry } from "./agent-registry.js";

interface TranslatedEntry {
  id: string;
  type: string;
  [key: string]: unknown;
}

let entryIdCounter = 0;
function nextId(agentId: string): string {
  return `bg-${agentId}-${++entryIdCounter}`;
}

/**
 * Create a transcript translator scoped to one background sub-agent. Returned
 * function is a StreamCallback drop-in: feed it the child Engine's events and
 * it maintains the agent's transcript in `asyncAgentRegistry`.
 */
export function createTranscriptTranslator(agentId: string): (event: StreamEvent) => void {
  // Local state for THIS agent. Background sub-agents run independently so
  // each gets its own translator; no cross-agent state.
  let streamingAssistantId: string | undefined;
  let thinkingId: string | undefined;
  // toolCallId → tool_start entry id. Lets tool_use_args_delta find the right
  // tool_start to patch.
  const toolStartByCallId = new Map<string, string>();

  function patchEntry(
    entryId: string,
    patch: (e: AgentTranscriptEntry) => AgentTranscriptEntry,
  ): void {
    const a = asyncAgentRegistry.get(agentId);
    if (!a?.transcript) return;
    const idx = a.transcript.findIndex((e) => e.id === entryId);
    if (idx < 0) return;
    a.transcript[idx] = patch(a.transcript[idx]!);
    asyncAgentRegistry.touchTranscript(agentId);
  }

  function dropEntry(entryId: string): void {
    const a = asyncAgentRegistry.get(agentId);
    if (!a?.transcript) return;
    a.transcript = a.transcript.filter((e) => e.id !== entryId);
    asyncAgentRegistry.touchTranscript(agentId);
  }

  function append(data: Omit<TranslatedEntry, "id">): string {
    const id = nextId(agentId);
    asyncAgentRegistry.appendToTranscript(agentId, {
      ...data,
      id,
    } as AgentTranscriptEntry);
    return id;
  }

  return (event: StreamEvent) => {
    switch (event.type) {
      // ── thinking ─────────────────────────────────────────────────
      case "stream_request_start": {
        if (thinkingId) {
          dropEntry(thinkingId);
          thinkingId = undefined;
        }
        thinkingId = append({ type: "thinking", agentId });
        break;
      }

      case "thinking_delta": {
        // Sub-agent thinking content is collapsed in the dock view — we
        // don't replicate the verb spinner. Keep the empty thinking
        // placeholder; renderEntry shows it as a spinner row.
        break;
      }

      // ── assistant text (streaming) ───────────────────────────────
      case "text_delta": {
        if (thinkingId) {
          dropEntry(thinkingId);
          thinkingId = undefined;
        }
        if (streamingAssistantId) {
          patchEntry(streamingAssistantId, (e) => ({
            ...e,
            text: String(e.text ?? "") + (event as any).text,
          }));
        } else {
          streamingAssistantId = append({
            type: "assistant_text",
            text: (event as any).text,
            streaming: true,
            agentId,
          });
        }
        break;
      }

      // ── tool call ────────────────────────────────────────────────
      case "tool_use_start": {
        if (streamingAssistantId) {
          patchEntry(streamingAssistantId, (e) => ({ ...e, streaming: false }));
          streamingAssistantId = undefined;
        }
        if (thinkingId) {
          dropEntry(thinkingId);
          thinkingId = undefined;
        }
        const tc = (event as any).toolCall;
        const startId = append({
          type: "tool_start",
          toolName: tc.toolName,
          args: tc.args,
          toolCallId: tc.id,
          agentId,
        });
        if (tc.id) toolStartByCallId.set(tc.id, startId);
        append({ type: "tool_running", toolName: tc.toolName, agentId });
        break;
      }

      case "tool_use_args_delta": {
        const ev = event as any;
        const startId = toolStartByCallId.get(ev.toolCallId);
        if (!startId) break;
        patchEntry(startId, (e) => ({ ...e, args: ev.args }));
        break;
      }

      case "tool_result": {
        const r = (event as any).result;
        const a = asyncAgentRegistry.get(agentId);
        if (a?.transcript) {
          a.transcript = a.transcript.filter(
            (e) => !(e.type === "tool_running" && (e as any).toolName === r.toolName),
          );
          asyncAgentRegistry.touchTranscript(agentId);
        }
        append({
          type: "tool_result",
          toolName: r.toolName,
          result: r.result,
          error: r.error,
          agentId,
        });
        break;
      }

      // ── lifecycle: finalize streaming on turn end ───────────────
      case "turn_complete":
      case "tombstone": {
        if (streamingAssistantId) {
          patchEntry(streamingAssistantId, (e) => ({ ...e, streaming: false }));
          streamingAssistantId = undefined;
        }
        if (thinkingId) {
          dropEntry(thinkingId);
          thinkingId = undefined;
        }
        break;
      }

      // ── errors surface as a card in the transcript ──────────────
      case "error": {
        if (thinkingId) {
          dropEntry(thinkingId);
          thinkingId = undefined;
        }
        append({
          type: "error",
          error: (event as any).error,
          agentId,
        });
        break;
      }

      default:
        break;
    }
  };
}

/**
 * Built-in Agent tool — spawn a sub-agent to handle a task.
 *
 * Creates a new Engine instance with its own transcript,
 * runs the task to completion, and returns the result text.
 * Supports AbortSignal for cascading cancellation.
 * Supports onStream for real-time output passthrough.
 */

import type { ToolDefinition, StreamCallback, SubAgentContinuation } from "../../types.js";
import type { ToolContext, SubAgentSpawner } from "../context.js";
import type { AgentDefinitionRegistry } from "../../agent/agent-definition-registry.js";
import type { AgentDefinition } from "../../agent/agent-definition.js";
import type { HookRegistry } from "../../hooks/registry.js";
import { asyncAgentRegistry, MAX_BACKGROUND_AGENTS } from "./agent-registry.js";
import type { ChildWriterLease, LiveChildControl } from "./agent-registry.js";
import { ensureAgentHeartbeat } from "./agent-heartbeat.js";
import { writeAgentOutputFile } from "./agent-output-file.js";
import { createTranscriptTranslator } from "./agent-transcript-translator.js";
import { notificationQueue } from "./agent-notifications.js";
import { nanoid } from "nanoid";
import { logger } from "../../logging/logger.js";
import {
  applyAgentProgressPhase,
  applyAgentProgressUsage,
  initialAgentProgress,
  reduceAgentProgress,
} from "./agent-progress.js";
import type { ProgressPayload } from "./agent-notifications.js";

/**

async function runSubAgent(
  spawner: SubAgentSpawner,
  opts: {
    agentId: string;
    name?: string;
    description: string;
    /** Resolved role name (e.g. "general-purpose", "explorer"); surfaced in
     *  the agent_start / agent_end markers so the UI can show the dispatched
     *  type. Undefined for a true ephemeral agent (empty registry). */
    agentType?: string;
    prompt: string;
    maxTurns: number;
    signal: AbortSignal;
    /** Role overrides resolved from agent_type; forwarded to spawner.spawn. */
    model?: string;
    toolAllowlist?: string[];
    skillAllowlist?: string[];
    sandboxMode?: AgentDefinition["sandbox"];
    mcpAllowlist?: string[];
    appendSystemPrompt?: string;
    readOnlySession?: boolean;
    /** Resume an existing child session (transcript replay) instead of cold
     *  start. Set by AgentSendInput; undefined for a first spawn. */
    resumeSessionId?: string;
    continuation?: SubAgentContinuation;
    /** Engine HookRegistry for lifecycle events. Undefined → no hooks. */
    hooks?: HookRegistry;
    /** Parent session/Goal accounting sink for the completed child run. */
    recordBilledUsage?: (usage: import("../../types.js").TokenUsage) => void;
    runtimeGeneration?: number;
    bindLiveControl?: (
      control: LiveChildControl,
      ownerToken: string,
    ) => ChildWriterLease | true | false;
    closeLiveControl?: (control: LiveChildControl, lease?: ChildWriterLease) => void;
    onProgressEvent?: (event: Parameters<StreamCallback>[0]) => void;
    onAgentProgress?: import("../../engine/run-types.js").EngineRunOptions["onAgentProgress"];
  },
  /**
   * Optional sink for the user-visible `agent_start` / `agent_end` markers.
   * Background path passes the parent's real onStream here; sync calls leave
   * it undefined and we fall back to `spawner.parentStream`.
   */
  uiStream?: StreamCallback,
  /**
   * Optional override for the spawned child Engine's per-event stream.
   * Background path mirrors per-event detail into its transcript and the
   * parent stream, where agentId keeps it scoped to the child card. Sync
   * calls leave undefined; engine.ts falls back to `spawner.parentStream`
   * (the parent UI), preserving the inline rendering of synchronous
   * sub-agents.
   */
  streamOverride?: StreamCallback,
): Promise<string> {
  const { agentId, name, description, agentType } = opts;
  const startEndSink = uiStream ?? spawner.parentStream;

  safeEmit(startEndSink, { type: "agent_start", agentId, name, description, agentType });
  emitSubAgentHook(opts.hooks, "subagent_start", { agentId, description });

  // `resetPlanMode` / `restorePlanMode` operated on a module-level singleton
  // that no longer exists. The child Engine is a fresh instance; plan-mode
  // isolation between parent and child is enforced via separate Engine
  // instances (finalized in T6).
  const { text, usage } = await spawner.spawn({ ...opts, streamOverride });
  if (usage) opts.recordBilledUsage?.(usage);
  const finalText = text || `Agent completed but produced no text output.`;
  safeEmit(startEndSink, {
    type: "agent_end",
    agentId,
    name,
    description,
    text: finalText,
    agentType,
  });
  emitSubAgentHook(opts.hooks, "subagent_finish", { agentId, description, text: finalText });
  return finalText;
}

function createAgentProgressTracker(agentId: string): {
  current: () => ProgressPayload;
  onEvent: (event: Parameters<StreamCallback>[0]) => void;
  onRuntime: NonNullable<import("../../engine/run-types.js").EngineRunOptions["onAgentProgress"]>;
} {
  let progress = initialAgentProgress();
  return {
    current: () => progress,
    onEvent: (event) => {
      progress = reduceAgentProgress(progress, event);
      asyncAgentRegistry.updateProgress(agentId, progress);
    },
    onRuntime: (event) => {
      progress =
        event.type === "usage"
          ? applyAgentProgressUsage(progress, event.usage)
          : applyAgentProgressPhase(progress, event.phase, Date.now(), event.toolName);
      asyncAgentRegistry.updateProgress(agentId, progress);
    },
  };
}

export async function agentTool(args: Record<string, unknown>, ctx?: ToolContext): Promise<string> {
  const prompt = args.prompt as string;
  const description = (args.description as string) || "sub-agent";
  const rawName = (args.name as string | undefined)?.trim();
  // Resolved below: when the model omits `name`, fall back to the resolved
  // kind name so the dock shows a meaningful label instead of bare "Agent".
  let name = rawName && rawName.length > 0 ? rawName : undefined;
  if (!prompt) return "Error: prompt is required";

  // Tag with the spawning session so the parent Engine.run waits only on
  // its own background agents (hasRunningForSession).
  sessionId: ctx?.sessionId,
  childSessionId: agentId,
  runtimeGeneration,
  progress: progressTracker.current(),
  status: "running",
  startedAt: Date.now(),
  abort: () => controller.abort(),
});

// B: liveness heartbeat for this explicit background agent too.
ensureAgentHeartbeat();

// Translate this background agent's per-event stream into ChatEntry-
// shaped rows inside its own transcript. The dock detail view reuses
// App.renderEntry which only understands ChatEntry types — storing
// raw StreamEvents would render as blanks. The translator mirrors
// App.tsx#handleStreamEvent's reduction but is scoped to one agent
// (per-instance closure state), so it doesn't interleave with other
// agents.
//
// Also forward the agent-scoped events so a desktop child card can show
// live operations even after the spawning parent turn has finished.
const transcriptSink: StreamCallback = createTranscriptTranslator(agentId);
const detailSink: StreamCallback = (event) => {
  transcriptSink(event);
  safeEmit(parentStream, event);
};
const lifecycleSink: StreamCallback = (event) => {
  safeEmit(parentStream, event);
  if (event.type === "agent_start") {
    // Mark detached before spawn can emit any detail. Otherwise the parent
    // turn's completion sweep prematurely seals this still-running card.
    safeEmit(parentStream, {
      type: "agent_backgrounded",
      agentId,
      name,
      description,
      agentType: overrides.resolvedType,
    });
  }
};

void runSubAgent(
  spawner,
  {
    agentId,
    name,
    description,
    agentType: overrides.resolvedType,
    prompt,
    continuation,
    maxTurns,
    model: overrides.model,
    toolAllowlist: overrides.toolAllowlist,
    skillAllowlist: overrides.skillAllowlist,
    sandboxMode: overrides.sandboxMode,
    mcpAllowlist: overrides.mcpAllowlist,
    appendSystemPrompt: overrides.appendSystemPrompt,
    readOnlySession:
      overrides.resolvedType === "researcher" || overrides.resolvedType === "explorer",
    hooks: ctx?.hooks,
    recordBilledUsage: ctx?.recordBilledUsage,
    runtimeGeneration,
    bindLiveControl: (control, ownerToken) => {
      const lease = asyncAgentRegistry.acquireWriterLease(
        control.childSessionId,
        control.runtimeGeneration,
        ownerToken,
      );
      if (!lease) return false;
      if (!asyncAgentRegistry.bindLiveControl(agentId, control, lease)) {
        asyncAgentRegistry.releaseWriterLease(lease);
        return false;
      }
      liveLease = lease;
      return lease;
    },
    closeLiveControl: (_control, lease) => {
      if (lease) asyncAgentRegistry.closeDirectionIntake(agentId, lease);
    },
    onProgressEvent: progressTracker.onEvent,
    onAgentProgress: progressTracker.onRuntime,
    signal: controller.signal,
  },
  lifecycleSink,
  detailSink,
)
  .then((text) => {
    if (controller.signal.aborted) {
      if (liveLease) asyncAgentRegistry.completeTerminal(agentId, "cancelled", liveLease);
      else asyncAgentRegistry.markCancelled(agentId);
      void ctx?.hooks?.emit("notification", {
        kind: "agent_cancelled",
        agentId,
        name,
        description,
      });
      return;
    }
    const transitioned = liveLease
      ? asyncAgentRegistry.completeTerminal(agentId, "completed", liveLease)
      : (asyncAgentRegistry.markCompleted(agentId), true);
    if (!transitioned) return;
    // External-readable copy of the result (tail / cross-session history).
    // Best-effort; never blocks the completion path.
    void writeAgentOutputFile(agentId, {
      status: "completed",
      body: text,
      description,
      name,
      onError: (m, meta) => logger.warn(m, meta),
    });
    // B2 / Gate 1: attribute completion to the session that spawned
    // this agent so concurrent sessions don't drain each other's

  type: "agent_end",
  agentId,
  name,
  description,
  error: err.message,
  agentType: overrides.resolvedType,
});
if (controller.signal.aborted) {
  // User-initiated cancel: mark status but do NOT enqueue —
  // the main agent doesn't need a follow-up turn. Dock still
  // shows the "cancelled" badge for the fade window.
  if (liveLease) asyncAgentRegistry.completeTerminal(agentId, "cancelled", liveLease);
  else asyncAgentRegistry.markCancelled(agentId);
  void ctx?.hooks?.emit("notification", {
    kind: "agent_cancelled",
    agentId,
    name,
    description,
  });
  return;
}
const transitioned = liveLease
  ? asyncAgentRegistry.completeTerminal(agentId, "failed", liveLease)
  : (asyncAgentRegistry.markFailed(agentId), true);
if (!transitioned) return;
void writeAgentOutputFile(agentId, {
  status: "failed",
  body: err.message,
  description,
  name,
  onError: (m, meta) => logger.warn(m, meta),

  toolCallIds: string[];
  complete: boolean;
  omissions: { path: string; reason: string }[];
}

export type StreamEvent = {
  /** Source wall-clock time (Unix milliseconds), retained across durable replay. */
  timestamp?: number;
  /** Transcript user-message event id that opened this run; scoped to the session. */
  runId?: string;
  clientMessageId?: string;
  /** Opaque Session-owned output cursor, independent of Host transport epochs. */
  outputCursor?: string;
  /** Original child cursor when a parent journals a forwarded mirror. */
  outputOriginCursor?: string;
  outputRecovery?: "incomplete";
} & StreamEventPayload;

type UserMessageDisplayPayload = {
  /** Journal replay projection. Image bytes remain in the canonical input. */
  transcriptMessage?: {
    cwd?: string;
    content:
      | string
      | (
          | { type: "text"; text: string }
          | { type: "image"; source: { media_type: string; byteLength: number } }
        )[];
    displayText?: string;
  };
  /** Browser-projected attachment display metadata, never file contents. */
  attachments?: {
    name: string;
    size: number;
    path?: string;
    absPath?: string;
    mime?: string;
  }[];
};

type StreamEventPayload =
  | ({ type: "turn_diff"; agentId?: string } & TurnDiffSnapshot)
  // Emitted once per run() as soon as the Engine has resolved the session
  // id (resume vs. create). Lets the client know the authoritative sid
  // *before* run() resolves, which matters for mid-turn `/sid` lookups.
  | {
      type: "session_started";
      sessionId: string;
      /** Persisted run identity replaced when this run opened the session. */
      previousRunId?: string;
      /** Start of the whole logical submission, before run preparation. */

// Emitted once, fire-and-forget, after the FIRST turn of a session
// completes: an LLM-generated one-line title for the sidebar. Best-effort
// — absent on failure / when aux model unavailable.
| { type: "session_title"; sessionId: string; title: string }
| { type: "stream_request_start"; turnNumber: number; messageId?: string; agentId?: string }
// A host-queued user message was spliced into the running turn at the
// turn-loop step boundary (Engine.enqueueSteer / 引导不打断注入). The client
// uses this to flip a queued "待注入" chip to "已注入". `id` echoes the host's
// queue-entry id so it can remove exactly that pending draft from its panel
// (insert-time and bubble-display are decoupled — the panel item lives until
// THIS event confirms the engine actually consumed it).
| ({
    type: "steer_injected";
    text: string;
    id?: string;
    /** New producers bind the queued input identity to this Session. */
    sessionId?: string;
  } & UserMessageDisplayPayload)
| { type: "text_delta"; text: string; tokens?: number; agentId?: string }
| { type: "tool_use_start"; toolCall: ToolCall; agentId?: string }
| {
    type: "tool_use_args_delta";
    toolCallId: string;
    args: Record<string, unknown>;
    agentId?: string;
  }
| { type: "tool_result"; result: ToolResult; agentId?: string }
| { type: "assistant_message"; message: Message; messageId?: string; agentId?: string }
| {
    type: "turn_complete";
    reason: TerminalReason;
    /** Final run result, after tool/steer/Goal continuations have settled. */
    text?: string;
    completionKind?: TurnCompletionKind;
    agentId?: string;
    /** Whole logical submission timing, independent of individual tool spans. */
    startedAt?: number;
    completedAt?: number;
    /** Monotonic elapsed milliseconds; unaffected by wall-clock adjustments. */
    durationMs?: number;
  }
// Goal mode visibility: emitted each time the goal judge re-prompts the
// model ("not_met", carries the judge's `gaps` + the running round count),
// when the goal is finally judged complete ("met", round = total rounds),
// and when the continuation cap / run budget forces a stop ("exhausted").
// The UI renders one marker bar per event so the user can count rounds.
// No extra LLM call — `gaps` reuses the verdict the judge already produced.
| {
    type: "goal_progress";
    /** Concrete goal instance; absent only on legacy replayed events. */
    goalId?: string;
    /** Edit/pause/resume revision for stale-event fencing. */
    revision?: number;
    status: "not_met" | "met" | "exhausted" | "approaching_limit";
    round: number;
    gaps?: string;
    /** For "approaching_limit": turns left before the maxTurns cap (TODO 3.1). */
    turnsRemaining?: number;
    /** For "approaching_limit": consecutive blocks left before maxStopBlocks (TODO 3.1). */
    stopBlocksRemaining?: number;
    /** For "approaching_limit": which ceiling is closest — drives UI copy + extend default. */
    nearest?: "turns" | "stopBlocks";
    agentId?: string;
  }
// Persistent goal lifecycle (CC /goal style). `goal_set` fires when a send
// establishes or REPLACES the session's active goal (`replaced` true on
// replace). `goal_cleared` fires on explicit clear (agent/goalClear) — the
// judge-met path emits goal_progress(met) instead. The UI keeps an
// "active goal" per session from these + goal_progress.
| {
    type: "goal_set";
    goalId?: string;
    revision?: number;
    objective: string;
    replaced: boolean;
    paused?: boolean;
  }
| {
    type: "goal_updated";

  }
| { type: "goal_cleared"; goalId?: string; revision?: number }
| { type: "error"; error: string; agentId?: string }
| { type: "tombstone"; messageId: string; agentId?: string }
| { type: "task_update"; tasks: TaskInfo[]; agentId?: string }

if (this.goalControlStopRequested) {
  messages = this.redactConsumedSensitiveToolResults(messages);
  return { text: finalText, reason: "completed", messages };
}
// Model call (with streaming fallback and max_output_tokens continuation)
this.modelStepTools = this.deps.getTools?.() ?? this.deps.tools;
retainSensitiveMetadata();
this.config.onStream?.({
  type: "stream_request_start",
  turnNumber: this.turnCount,
  messageId: assistantMessageId,
});
// Track tool IDs streamed during this turn to avoid duplicate UI events
this.streamedToolIds.clear();
// Tool queue is created before the call, but enqueue happens only after
// the complete LLMResponse is available below.
const streamingQueue = new StreamingToolQueue(this.deps.toolExecutor, {
  // Once a trusted reply tool commits the authoritative host response,
  // later sequential calls from the same model batch must not execute.
  // Concurrency-safe calls may already be running; drain still awaits
  // those so the transcript remains complete.
  pendingUnsafeSkipReason: () =>
    this.deps.peekToolRunYield?.("reply_committed")
      ? "an authoritative host reply was already committed"
      : undefined,
});
let response;
try {
  this.deps.contextNotes?.markModelBoundary();
  response = await this.callModelWithFallback(messages, assistantMessageId);
} catch (err) {
  if (err instanceof ContextLimitError) {
    if (this.goalControlStopRequested) {
      messages = this.redactConsumedSensitiveToolResults(messages);
      return { text: finalText, reason: "completed", messages };
    }
    // Progressive recovery: drop oldest API rounds, up to 3 retries
    const { dropOldestRounds } = await import("../context/compaction.js");

// it raised a misleading "Missing required parameter: file_path". Instead,
// tell the model its output was truncated and let the next turn retry —
// bounded by the outer maxTurns loop.
if (
  !budgetTermination &&
  isTruncatedStop(response.stopReason) &&
  response.toolCalls.length > 0
) {
  tlog.info("turn.truncated_tool_call", {
    cat: "turn",
    toolCount: response.toolCalls.length,
  });
  if (response.text) {
    messages.push({ role: "assistant", content: response.text });
  }
  // Anthropic streams tool_use_start as soon as the content block
  // opens. If max_tokens cuts the JSON arguments off, we deliberately
  // do not execute that call, but the renderer still needs a terminal
  // event for the already-open card. Without it Claude tool cards stay
  // "working" forever (often until a later context compaction hides
  // them), even though the loop has moved on to a retry.
  for (const toolCall of response.toolCalls) {
    this.config.onStream?.({
      type: "tool_result",
      result: {
        id: toolCall.id,
        toolName: toolCall.toolName,
        error: "Tool call was not executed because its arguments were truncated.",
        isError: true,
      },
    });
  }
  this.appendContextReminder(messages, {
    role: "user",
    content:
      "<system-reminder>Your previous response was truncated by the max output token limit before the tool call finished, so its arguments are incomplete. Do not assume it ran. Either retry with a smaller/more focused tool call (e.g. write the file in sections via Edit), or raise this model's maxOutputTokens.</system-reminder>",
  });
  this.finalizeModelTurn();
  continue;
}

// NOT added to the assistant message below, so the model never sees a
// result for them. Without a heads-up it assumes all ran (acting on
// tool output that never happened). Remember the dropped ones so we can
// inject a reminder after the executed batch's results. (B-3)
const droppedToolCalls = response.toolCalls.slice(this.config.maxToolCallsPerTurn);

// Add assistant message with tool_use blocks to messages
const assistantBlocks: ContentBlock[] = [];
if (response.text) {
  assistantBlocks.push({ type: "text", text: response.text });
}
for (const tc of toolCalls) {
  assistantBlocks.push({
